
const K='FIREBDTOUR_NEON_DATA_V2';
const APPLOGO='data:image/jpeg;base64,';
const IMG={"banner": "data:image/jpeg;base64,", "br": "data:image/jpeg;base64,", "solo": "data:image/jpeg;base64,", "squad": "data:image/jpeg;base64,", "cs": "data:image/jpeg;base64,", "lone": "data:image/jpeg;base64,", "give": "data:image/jpeg;base64,"};
const CATS=[['br','BR MATCH'],['solo','BR SURVIVAL'],['squad','CLASH SQUAD'],['cs','CS 2 VS 2'],['lone','LONE WOLF'],['give','FREE MATCH GIVEAWAY']];
function D(){const base={users:[],matches:[],deposits:[],withdrawals:[],settings:{bkash:{available:true,number:'01333413567',color:'#e21378'},nagad:{available:false,number:'',color:'#f28c18'},rocket:{available:false,number:'',color:'#6d35c9'},support:{enabled:true,telegram:''}},images:{}};let raw=localStorage.getItem(K);let d=raw?JSON.parse(raw):base;d.users=d.users||[];d.matches=d.matches||[];d.deposits=d.deposits||[];d.withdrawals=d.withdrawals||[];d.settings={...base.settings,...(d.settings||{})};for(const k of ['bkash','nagad','rocket'])d.settings[k]={...base.settings[k],...(d.settings[k]||{})};d.settings.support={...base.settings.support,...(d.settings.support||{})};d.images=d.images||{};return d}
function matchStart(m){let v=Number(m.startAt);if(Number.isFinite(v)&&v>0)return v;let raw=m.startAt||m.startTime||m.dateTime||m.start||'';let t=Date.parse(raw);return Number.isFinite(t)?t:0}function visibleMatches(d){const now=Date.now(),cutoff=180000;return d.matches.filter(m=>{const st=matchStart(m);if(!st)return true;return now<st+cutoff})}
function S(d){localStorage.setItem(K,JSON.stringify(d))} function imgFor(d,k){return (d.images&&d.images[k])||IMG[k]||''} function me(){let d=D();return d.users.find(x=>x.email===localStorage.getItem('email'))}
function money(n){return Number(n||0).toLocaleString()+' TK'} function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function nav(a){return `<div class="bottom"><button class="${a==='play'?'on':''}" onclick="play()"><span class="ico">🎮</span>Play</button><button class="${a==='my'?'on':''}" onclick="myMatches()"><span class="ico">📋</span>My Matches</button><button class="${a==='result'?'on':''}" onclick="results()"><span class="ico">📊</span>Results</button><button class="${a==='profile'?'on':''}" onclick="profile()"><span class="ico">👤</span>Profile</button></div>`}
function shell(title,body,a){let d=D(),sup=d.settings.support||{};document.body.innerHTML=`<div class="app"><div class="top"><img class="appLogo" src="${APPLOGO}" alt="FIREBDTOUR"><span class="brand">FIREBDTOUR</span><button class="supportLabel" onclick="supportCenter()">☎ সাহায্য কেন্দ্র</button><span class="bal">${me()?money(me().balance):''}</span></div><div class="screen">${body}</div>${nav(a)}</div>`}
function login(){document.body.innerHTML=`<div class="login"><div class="loginbox"><div style="font-size:44px">🔥</div><h1>FIREBDTOUR</h1><p style="color:#aaa0c7">PLAYER LOGIN</p><form id="lf" class="form"><input class="input" name="e" type="email" placeholder="Gmail" autocomplete="username" required><input class="input" name="p" type="password" placeholder="Password" autocomplete="current-password" required><button class="btn purple" style="width:100%;margin-top:7px">LOGIN</button></form><div style="margin-top:14px;color:#9b91b4">New player? <span class="neon-link" onclick="register()">CREATE ACCOUNT / REGISTER</span></div><div id="loginMsg" style="margin-top:10px;color:#ff8a8a"></div></div></div>`;document.getElementById('lf').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),d=D(),em=String(f.get('e')||'').trim().toLowerCase(),u=d.users.find(x=>x.email===em);let msg=document.getElementById('loginMsg');if(!u){msg.textContent='এই Gmail দিয়ে account নেই — REGISTER করুন।';return}if(u.pass!==f.get('p')){msg.textContent='Password ভুল।';return}if(u.status==='banned'){msg.textContent='Your account is banned.';return}localStorage.setItem('email',u.email);play()}}
function register(){document.body.innerHTML=`<div class="login"><div class="loginbox"><div style="font-size:44px">🔥</div><h1>FIREBDTOUR</h1><p style="color:#aaa0c7">CREATE PLAYER ACCOUNT</p><form id="rf" class="form"><input class="input" name="n" placeholder="Full Name" autocomplete="name" required><input class="input" name="e" type="email" placeholder="Gmail" autocomplete="email" required><input class="input" name="p" type="password" minlength="6" placeholder="Password (minimum 6 characters)" autocomplete="new-password" required><input class="input" name="pc" type="password" minlength="6" placeholder="Confirm Password" autocomplete="new-password" required><button class="btn green" style="width:100%;margin-top:7px">REGISTER</button></form><div style="margin-top:14px;color:#9b91b4">Already registered? <span class="neon-link" onclick="login()">BACK TO LOGIN</span></div><div id="regMsg" style="margin-top:10px;color:#ff8a8a"></div></div></div>`;document.getElementById('rf').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),d=D(),em=String(f.get('e')||'').trim().toLowerCase(),msg=document.getElementById('regMsg');if(String(f.get('p'))!==String(f.get('pc'))){msg.textContent='Password মিলছে না।';return}if(d.users.some(x=>x.email===em)){msg.textContent='এই Gmail দিয়ে আগে থেকেই Register করা আছে।';return}d.users.push({id:Date.now(),name:String(f.get('n')).trim(),email:em,pass:String(f.get('p')),balance:0,level:0,status:'active',totalPlayed:0,totalWin:0});S(d);localStorage.setItem('email',em);play()}}
function requireUser(){let u=me();if(!u){login();return null}if(u.status==='banned'){alert('Your account is banned');localStorage.removeItem('email');login();return null}return u}
function openBannerLink(){let d=D(),v=String(d.images?.bannerLink||'').trim();if(!v)return;if(!/^https?:\/\//i.test(v))v='https://'+v;window.open(v,'_blank','noopener,noreferrer')}
function play(){if(!requireUser())return;let d=D(),vm=visibleMatches(d),cards=CATS.map(c=>`<button class="cat" onclick="category('${c[0]}')"><img src="${imgFor(d,c[0])}"><div class="ct">${c[1]}</div><small>${vm.filter(m=>m.category===c[0]).length} matches found</small></button>`).join('');let banner=imgFor(d,'banner'),link=String(d.images?.bannerLink||'').trim();shell('Play',`<div class="hero ${link?'hasBannerLink':''}" ${link?'onclick="openBannerLink()" role="link" tabindex="0"':''}><img src="${banner}" alt="Play Banner">${link?'<div class="bannerLinkHint">TAP TO OPEN</div>':''}<div class="dots">• ● • • • • •</div></div><div class="notice">FIREBDTOUR — PLAY, COMPETE & WIN</div><div class="title">FREE FIRE</div><div class="cats">${cards}</div>`,'play')}
function category(c){if(!requireUser())return;let d=D(),ms=visibleMatches(d).filter(m=>m.category===c || String(m.category).toLowerCase()===String(c).toLowerCase()),cat=CATS.find(x=>x[0]===c),nm=cat?cat[1]:c,ci=imgFor(d,c);shell(nm,`<div class="categoryPage"><button class="btn gray" onclick="play()">← Back</button><div class="categoryHero"><img src="${ci}" alt="${nm}"><div class="categoryHeroTitle">${nm}</div></div>${ms.length?ms.map(matchCard).join(''):'<div class="card" style="text-align:center;padding:35px;color:#aaa"><h3>No match found</h3><p>Admin এখনো এই category-তে Match add করেনি।</p></div>'}</div>`,'play');ms.forEach(m=>timer(m.id))}
function matchCard(m){let u=me(),joined=(m.buyers||[]).includes(u.email),left=Math.max(0,(m.max||48)-m.buyers.length),started=Date.now()>=m.startAt,p=Math.min(100,m.buyers.length/(m.max||48)*100);return `<div class="match"><div class="mh matchHeadClick" onclick="matchInfo('${m.id}')"><img class="thumb" src="${m.image||imgFor(d,m.category)}" alt="${esc(m.title)}"><div><b>${esc(m.title)}</b><div>${new Date(matchStart(m)).toLocaleString()}</div><small style="color:#a99fc5">Tap match for rules</small></div></div><div class="stats"><div>WIN PRIZE<b>${money(m.prize)}</b></div><div>ENTRY TYPE<b>${esc(m.entryType||'Solo')}</b></div><div>ENTRY FEE<b>${money(m.entry)}</b></div><div>PER KILL<b>${money(m.kill)}</b></div><div>MAP<b>${esc(m.map||'Bermuda')}</b></div><div>VERSION<b>${esc(m.version||'Mobile')}</b></div></div><div class="prog"><i style="width:${p}%"></i></div><div style="padding:0 10px;color:#777;font-size:12px">${left} spots left • ${m.buyers.length}/${m.max||48}</div>${joined?`<div class="actions joinedActions"><button class="btn roomBig" onclick="room('${m.id}')">🔐 ROOM DETAILS</button></div>`:`<div class="actions"><button class="btn purple buyBig" onclick="buy('${m.id}')" ${started||!left?'disabled':''}>${started?'Started':!left?'Full':'BUY NOW'}</button></div>`}<div class="start">${started?'MATCH STARTED':`STARTS IN <span id="t_${m.id}">--:--</span>`}</div></div>`}
function timer(id){let m=D().matches.find(x=>x.id===id),e=document.getElementById('t_'+id);if(m)m.startAt=matchStart(m);if(!m||!e)return;let f=()=>{let diff=Math.floor((m.startAt-Date.now())/1000);if(diff<=0){if(Date.now()-m.startAt>=180000){location.reload();return}e.textContent='MATCH STARTED';setTimeout(f,500);return}e.textContent=String(Math.floor(diff/60)).padStart(2,'0')+':'+String(diff%60).padStart(2,'0');setTimeout(f,500)};f()}
function teamCount(team){return team==='Squad'?4:team==='Duo'?2:1}
function renderTeamFields(){let team=document.getElementById('team')?.value||'Solo',n=teamCount(team),box=document.getElementById('teamFields');if(!box)return;box.innerHTML=Array.from({length:n},(_,i)=>`<div class="teamMember" style="margin-top:10px;padding:10px;border:1px solid #3c286b;border-radius:12px;background:#0d0920"><b>${i+1} নং FF Gamer</b><input id="gid_${i}" class="input" placeholder="Free Fire Game ID দিন" style="margin-top:8px"><input id="gn_${i}" class="input" placeholder="Free Fire Game Name দিন" style="margin-top:8px"></div>`).join('')}
function buy(id){let u=requireUser();if(!u)return;let m=D().matches.find(x=>x.id===id);if(!m||m.buyers.includes(u.email))return;if(Date.now()>=m.startAt)return alert('Match already started.');if((m.max||48)<=m.buyers.length)return alert('Match Full');if(u.balance<m.entry)return alert('Balance কম');let type=(m.entryType||'Solo').toLowerCase();let opts=type.includes('squad')?['Solo','Duo','Squad']:type.includes('duo')?['Solo','Duo']:['Solo'];show(`<button class="close" onclick="closeM()">✕</button><h2>Team Select করুন</h2><div class="teamOptions">${opts.map((o,i)=>`<button class="teamOpt ${i===0?'selected':''}" data-team="${o}" onclick="pickTeam(this)">${o}</button>`).join('')}</div><input id="team" type="hidden" value="${opts[0]}"><h3>${esc(m.title)}</h3><p>প্রথমে FF Gamer ID ও Name দিন</p><p>Entry ${money(m.entry)}</p><div id="teamFields"></div><div class="grid2" style="margin-top:12px"><button class="btn gray" onclick="closeM()">REJECT</button><button class="btn green" onclick="pay('${id}')">CONFIRM & PAY</button></div>`);renderTeamFields()}
function pickTeam(el){document.querySelectorAll('.teamOpt').forEach(x=>x.classList.remove('selected'));el.classList.add('selected');document.getElementById('team').value=el.dataset.team;renderTeamFields()}
function pay(id){let team=document.getElementById('team')?.value||'Solo',n=teamCount(team),players=[];for(let i=0;i<n;i++){let gid=document.getElementById('gid_'+i)?.value.trim(),gn=document.getElementById('gn_'+i)?.value.trim();if(!gid||!gn)return alert(`${i+1} নং FF Gamer-এর Free Fire Game ID এবং Free Fire Game Name দিন`);players.push({gamerId:gid,gamerName:gn})}let d=D(),m=d.matches.find(x=>x.id===id),u=d.users.find(x=>x.email===localStorage.getItem('email'));if(!m||!u)return;if(u.balance<m.entry)return alert('Balance কম');if(Date.now()>=m.startAt)return alert('Match already started.');if(m.buyers.includes(u.email))return alert('Already purchased');if((m.max||48)<=m.buyers.length)return alert('Match Full');u.balance-=m.entry;m.buyers.push(u.email);m.players=m.players||[];m.players.push({email:u.email,team,players,paid:m.entry});u.totalPlayed=(u.totalPlayed||0)+1;S(d);closeM();category(m.category)}
function supportCenter(){let d=D(),s=d.settings.support||{};if(!s.enabled||!s.telegram)return show(`<button class="close" onclick="closeM()">✕</button><h2>সহায়তা কেন্দ্র</h2><p>Admin এখনো Telegram support link দেননি।</p>`);let url=s.telegram.trim();if(!/^https?:\/\//i.test(url))url='https://'+url;show(`<button class="close" onclick="closeM()">✕</button><h2>সহায়তা কেন্দ্র</h2><p>যেকোনো সাহায্যের জন্য আমাদের Telegram-এ যোগাযোগ করুন।</p><button class="btn purple" style="width:100%" onclick="window.open('${url.replace(chr(39),'%27')}','_blank')">📞 Telegram-এ কথা বলুন</button>`)}
function room(id){
 let u=requireUser();if(!u)return;
 let d=D(),m=d.matches.find(x=>String(x.id)===String(id));
 if(!m)return alert('Match not found');
 if(!(m.buyers||[]).includes(u.email))return alert('শুধু purchased player Room Details দেখতে পারবে।');
 let release=Number(m.releaseAt);
 if(!Number.isFinite(release)||release<1)release=0;
 let released=!release||Date.now()>=release;
 if(!released){
   let mins=Math.max(0,Math.ceil((release-Date.now())/60000));
   return show(`<button class="close" onclick="closeM()">✕</button><h2>ROOM DETAILS</h2><div class="roomNotice"><b>Room ID / Password এখনো release হয়নি।</b><div class="roomCountdown">প্রায় ${mins} মিনিট পরে দেখা যাবে।</div></div><div class="roomBtns"><button class="btn purple" onclick="room('${id}')">REFRESH</button><button class="btn gray" onclick="closeM()">CLOSE</button></div>`);
 }
 let rid=String(m.roomId??m.roomID??m.room_id??'').trim();
 let rp=String(m.roomPass??m.roomPassword??m.password??m.room_password??'').trim();
 return show(`<button class="close" onclick="closeM()">✕</button><h2>ROOM DETAILS</h2><div class="roomInfo"><p><b>ROOM ID</b><br><span style="font-size:20px;color:#fff">${esc(rid||'Not set')}</span></p><p><b>ROOM PASSWORD</b><br><span style="font-size:20px;color:#fff;word-break:break-all">${esc(rp||'Not set')}</span></p></div><div class="roomBtns"><button class="btn purple" onclick="room('${id}')">REFRESH</button><button class="btn gray" onclick="closeM()">CLOSE</button></div>`);
}
function profile(){let u=requireUser();if(!u)return;shell('Profile',`<div class="profileHead"><div class="avatar">👤</div><h2>${esc(u.name)}</h2><div class="profileStats"><div><b>${u.totalPlayed||0}</b><br>মোট ম্যাচ খেলেছেন</div><div><b>${money(u.balance)}</b><br>Wallet</div><div><b>${u.totalWin||0}</b><br>এখন পর্যন্ত জিতেছেন</div></div></div><div class="menu"><button onclick="wallet()">💼 Wallet</button><button onclick="withdraw()">🧾 Withdraw</button><button onclick="profileInfo()">👤 My Profile</button><button onclick="rules()">📋 All Rules <span style="float:right">›</span></button><button onclick="topPlayers()">📈 Top Players</button><button onclick="developer()">‹/› Developer Profile</button></div><button class="btn blue logout" style="width:calc(100% - 20px)" onclick="localStorage.removeItem('email');login()">Logout</button>`,'profile')}
function wallet(){if(!requireUser())return;let u=me();shell('Wallet',`<div class="title" style="padding-top:16px">WALLET</div><div class="walletHero"><div style="color:#cfc5e6;font-weight:800">AVAILABLE BALANCE</div><div class="amount">${money(u.balance)}</div></div><div class="walletAction"><button class="btn purple" onclick="deposit()">➕ ADD MONEY</button><button class="btn green" onclick="withdraw()">💸 WITHDRAW</button></div><div class="card"><b>Wallet Balance</b><p class="paymentHint">Admin deposit approve করলে পাঠানো টাকা এই balance-এ যোগ হবে। Match entry কিনলে এখান থেকেই টাকা কাটা হবে।</p></div>`,'profile')}
function profileInfo(){let u=me();show(`<button class="close" onclick="closeM()">✕</button><h2>My Profile</h2><p>Name: <b>${esc(u.name)}</b></p><p>Gmail: <b>${esc(u.email)}</b></p><p>Level: <b>${u.level}</b></p>`)}
function rules(){show(`<button class="close" onclick="closeM()">✕</button><h2>All Rules</h2><p>1. Level 40-এর নিচে Join করলে ban করা হবে।</p><p>2. Hack / panel / script / unfair tool ব্যবহার নিষিদ্ধ।</p><p>3. Fake payment বা fraud করলে account ban হতে পারে।</p><p>4. Room ID/Password শুধু purchased player release time-এর পরে দেখতে পারবে।</p>`)}
function topPlayers(){let d=D(),a=[...d.users].sort((x,y)=>(y.totalWin||0)-(x.totalWin||0));show(`<button class="close" onclick="closeM()">✕</button><h2>Top Players</h2>${a.map((x,i)=>`<p>${i+1}. ${esc(x.name)} — ${x.totalWin||0} wins</p>`).join('')||'<p>No players yet.</p>'}`)}
function developer(){show(`<button class="close" onclick="closeM()">✕</button><h2>Developer Profile</h2><p>FIREBDTOUR Tournament Platform</p>`)}
function deposit(){if(!requireUser())return;let d=D();shell('Add Money',`<div class="title" style="padding-top:16px">ADD MONEY</div><div class="card"><div class="row"><span>Current Balance</span><b style="color:#ffd34e">${money(me().balance)}</b></div></div><div class="card" style="margin-bottom:12px"><h3>ADMIN CREDIT CODE</h3><p class="paymentHint">Admin যদি আপনাকে একটি credit code দেয়, এখানে দিলে কোনো payment ছাড়াই সেই নির্দিষ্ট টাকা একবারে balance-এ যোগ হবে।</p><div class="actions"><input id="creditCode" class="input" placeholder="Enter credit code"><button class="btn purple" onclick="redeemCredit()">REDEEM</button></div></div><div class="payTabs">${['bkash','nagad','rocket'].map(k=>{let s=d.settings[k];return `<button class="payTab ${s.available?'':'off'}" onclick="pm('${k}')">${k==='bkash'?'bKash':k[0].toUpperCase()+k.slice(1)}${s.available?'':'<br><small>NOT AVAILABLE</small>'}</button>`}).join('')}</div><div id="pm"></div>`,'profile');pm('bkash')}
function pm(k){let d=D(),s=d.settings[k],el=document.getElementById('pm');if(!el)return;if(!s.available){el.innerHTML=`<div class="card"><h3>${k.toUpperCase()}</h3><p>NOT AVAILABLE</p></div>`;return}let name=k==='bkash'?'bKash':k[0].toUpperCase()+k.slice(1),color=s.color||'#7b4dff';el.innerHTML=`<div class="bkashBox" style="background:linear-gradient(145deg,${color},#24123f)"><div class="sendTitle">${name} Send Money করবেন</div><p>নিচের ${name} নম্বরে টাকা Send Money করুন। টাকা পাঠানোর পর Amount এবং TRXID দিয়ে Submit করুন।</p><div class="bkashNum">${esc(s.number||'Number not set')}</div><input id="da" class="input trxInput" type="number" min="1" placeholder="Amount — কত টাকা পাঠিয়েছেন"><input id="dt" class="input trxInput" placeholder="TRXID — Transaction ID"><button class="btn" style="width:100%;background:#fff;color:${color}" onclick="sendDep('${k}')">SUBMIT PAYMENT</button></div>`}
function sendDep(k){let a=+document.getElementById('da').value,t=document.getElementById('dt').value.trim();if(a<=0||!t)return alert('Amount এবং TRXID দিন');let d=D(),s=d.settings[k];d.deposits.push({id:Date.now(),email:me().email,method:k,number:s.number||'',amount:a,trx:t,trxId:t,status:'pending'});S(d);alert('Payment request submitted. Admin verify করলে balance-এ টাকা যোগ হবে।');deposit()}
function redeemCredit(){if(!requireUser())return;let code=((document.getElementById('creditCode')||{}).value||'').trim().toUpperCase();if(!code)return alert('Redeem code দিন');let d=D(),list=d.redeems||[],x=list.find(a=>a.code===code&&!a.cancelled);if(!x)return alert('Invalid / cancelled redeem code');x.redeemedBy=x.redeemedBy||[];let email=me().email;if(x.redeemedBy.includes(email))return alert('আপনি এই code আগে ব্যবহার করেছেন');if(x.redeemedBy.length>=Number(x.maxUses||1))return alert('এই redeem code-এর সব ব্যবহার শেষ');let u=d.users.find(a=>a.email===email);if(!u)return;u.balance=Number(u.balance||0)+Number(x.amount||0);x.redeemedBy.push(email);x.lastRedeemedAt=Date.now();S(d);alert(money(x.amount)+' আপনার balance-এ যোগ হয়েছে।');deposit()}
function withdraw(){if(!requireUser())return;let u=me();shell('Withdraw',`<div class="title" style="padding-top:16px">WITHDRAW</div><div class="walletHero"><div style="color:#cfc5e6;font-weight:800">AVAILABLE BALANCE</div><div class="amount">${money(u.balance)}</div></div><div class="payTabs"><button class="payTab active" onclick="wd('bkash')">bKash</button><button class="payTab off" onclick="wd('nagad')">Nagad<br><small>NOT AVAILABLE</small></button><button class="payTab off" onclick="wd('rocket')">Rocket<br><small>NOT AVAILABLE</small></button></div><div id="wd"></div>`,'profile');wd('bkash')}
function wd(k){let s=D().settings[k],el=document.getElementById('wd');if(!el)return;if(!s.available){el.innerHTML=`<div class="card"><h3>${k.toUpperCase()}</h3><p>NOT AVAILABLE — এখন এই মাধ্যমে Withdraw করা যাবে না।</p></div>`;return}el.innerHTML=`<div class="card"><h3>${k.toUpperCase()} WITHDRAW</h3><input id="wn" class="input" placeholder="${k} Number"><input id="wa" class="input" type="number" min="100" placeholder="Amount (minimum 100 TK)"><button class="btn green" style="width:100%" onclick="sendWd()">WITHDRAW MONEY</button></div>`}
function sendWd(){let a=+document.getElementById('wa').value,n=document.getElementById('wn').value.trim(),d=D(),u=d.users.find(x=>x.email===localStorage.getItem('email'));if(!u)return;if(!n||a<100||a>Number(u.balance||0))return alert('Number দিন এবং minimum 100 TK / balance check করুন');u.balance=Number(u.balance||0)-a;d.withdrawals.push({id:Date.now(),email:u.email,method:'bkash',account:n,number:n,amount:a,status:'pending',debited:true});S(d);alert('Withdrawal request sent. '+money(a)+' balance থেকে কেটে নেওয়া হয়েছে। Admin approve করলে process হবে।');withdraw()}
function show(x){let e=document.createElement('div');e.className='modal';e.innerHTML=`<div class="modalbox">${x}</div>`;document.body.appendChild(e)} function closeM(){document.querySelector('.modal')?.remove()}
if(localStorage.getItem('email') && me())play();else {localStorage.removeItem('email');login();}


/* FIREBDTOUR UPDATE: My Matches + Results + Notifications */
function getUserPurchases(){let d=D(),u=requireUser();if(!u)return[];return d.matches.filter(m=>(m.buyers||[]).includes(u.email));}
function myMatches(){if(!requireUser())return;let d=D(),u=me(),ms=d.matches.filter(m=>(m.buyers||[]).includes(u.email)).sort((a,b)=>matchStart(b)-matchStart(a));shell('My Matches',`<div class="pageHead"><h2>MY MATCHES</h2><div class="muted">আপনি মোট <b>${ms.length}</b> টি match কিনেছেন / joined করেছেন।</div></div>${ms.length?ms.map(m=>{let p=(m.players||[]).find(x=>x.email===u.email);return `<div class="card myMatchCard"><div class="row"><div><b>${esc(m.title)}</b><div class="muted">${esc(catNameUser(m.category))}</div></div><span class="pill ${m.resultPublished?'active':'pending'}">${m.resultPublished?'RESULT':'JOINED'}</span></div><div class="myMatchGrid"><div>ENTRY<br><b>${money(m.entry)}</b></div><div>START<br><b>${new Date(matchStart(m)).toLocaleString()}</b></div><div>TEAM<br><b>${esc(p?.team||m.entryType||'Solo')}</b></div><div>STATUS<br><b>${Date.now()>=matchStart(m)?'Played/Started':'Upcoming'}</b></div></div>${p?.players?.length?`<div class="muted">${p.players.map((g,i)=>`${i+1}. ${esc(g.gamerName||'')} — ${esc(g.gamerId||'')}`).join('<br>')}</div>`:''}<div class="actions">${Date.now()<matchStart(m)?'':`<button class="btn roomBig" onclick="room('${m.id}')">🔐 ROOM DETAILS</button>`}</div></div>`}).join(''):'<div class="card emptyState">এখনও কোনো match কেনা হয়নি। Play থেকে match কিনুন।</div>'}`,'my');}
function catNameUser(k){return (CATS.find(c=>c[0]===k)||['',k])[1]}
function results(){if(!requireUser())return;let d=D(),u=me(),ms=d.matches.filter(m=>(m.buyers||[]).includes(u.email)&&m.resultPublished).sort((a,b)=>(b.resultAt||matchStart(b))-(a.resultAt||matchStart(a)));let total=ms.reduce((sum,m)=>sum+Number((m.resultsByUser||{})[u.email]||0),0);shell('Results',`<div class="pageHead"><h2>RESULTS</h2><div class="resultTotal">মোট জিতেছেন <b>${money(total)}</b></div></div>${ms.length?ms.map(m=>{let win=Number((m.resultsByUser||{})[u.email]||0);return `<div class="card resultCard"><div class="row"><div><b>${esc(m.title)}</b><div class="muted">${esc(catNameUser(m.category))}</div></div><span class="winAmount">+${money(win)}</span></div><div class="muted">Match Prize: ${money(m.prize)} · ${m.resultAt?new Date(m.resultAt).toLocaleString():''}</div></div>`}).join(''):'<div class="card emptyState">এখনও কোনো result publish হয়নি।</div>'}`,'result');}
function notifications(){if(!requireUser())return;let d=D(),u=me(),ns=(d.notifications||[]).filter(n=>n.audience==='all'||n.email===u.email).sort((a,b)=>Number(b.createdAt||0)-Number(a.createdAt||0));shell('Notifications',`<div class="pageHead"><h2>🔔 NOTIFICATIONS</h2><div class="muted">${ns.length} টি notification</div></div>${ns.length?ns.map(n=>`<div class="card noticeCard"><div class="row"><b>${esc(n.title||'Notification')}</b><small class="muted">${n.createdAt?new Date(n.createdAt).toLocaleString():''}</small></div><p>${esc(n.message||'')}</p></div>`).join(''):'<div class="card emptyState">কোনো notification নেই।</div>'}`,'notification');}
function nav(a){return `<div class="bottom"><button class="${a==='play'?'on':''}" onclick="play()"><span class="ico">🎮</span>Play</button><button class="${a==='my'?'on':''}" onclick="myMatches()"><span class="ico">📋</span>My Matches</button><button class="${a==='result'?'on':''}" onclick="results()"><span class="ico">📊</span>Results</button><button class="${a==='notification'?'on':''}" onclick="notifications()"><span class="ico">🔔</span>Notification</button><button class="${a==='profile'?'on':''}" onclick="profile()"><span class="ico">👤</span>Profile</button></div>`}
function play(){if(!requireUser())return;let d=D(),vm=visibleMatches(d),cards=CATS.map(c=>`<button class="cat" onclick="category('${c[0]}')"><img src="${imgFor(d,c[0])}" alt="${c[1]}"><div class="ct">${c[1]}</div><small>${vm.filter(m=>String(m.category).toLowerCase()===String(c[0]).toLowerCase()).length} matches found</small></button>`).join('');let banner=imgFor(d,'banner');shell('Play',`<div class="heroBanner" onclick="openBannerLink()" style="${d.images?.bannerLink?'cursor:pointer':''}"><img src="${banner}" alt="FIREBDTOUR"></div><div class="cats">${cards}</div>`,'play');}
window.addEventListener('storage',e=>{if(e.key===K&&localStorage.getItem('email')){let active=document.querySelector('.bottom .on');if(active&&active.textContent.includes('Notification'))notifications();}});

function supportCenter(){let d=D(),s=d.settings.support||{};if(!s.enabled||!s.telegram)return show(`<button class="close" onclick="closeM()">✕</button><h2>সহায়তা কেন্দ্র</h2><p>Admin এখনো Telegram support link দেননি।</p>`);let url=String(s.telegram).trim();if(!/^https?:\/\//i.test(url))url='https://'+url;show(`<button class="close" onclick="closeM()">✕</button><h2>সহায়তা কেন্দ্র</h2><p>যেকোনো সাহায্যের জন্য আমাদের Telegram-এ যোগাযোগ করুন।</p><button class="btn purple" style="width:100%" onclick="window.open('${esc(url)}','_blank')">📞 Telegram-এ কথা বলুন</button>`)}
